const median = values => {const a=values.filter(finite).sort((a,b)=>a-b); if (!a.length) return null; const m=Math.floor(a.length/2); return a.length%2 ? a[m] : (a[m-1]+a[m])/2;};
const orderAccount = name => name === 'Principal' ? 0 : name === 'BaltigoFlix' ? 1 : name === 'AniNexus' ? 2 : 3 + (Number(String(name).replace(/\D/g,'')) || 99);
const accountLabel = name => /^Conta\d+$/.test(name) ? name.replace('Conta','Conta ') : name;
const cleanName = name => String(name || '').replace(/[\p{Extended_Pictographic}\p{Regional_Indicator}\uFE0F\u200D]/gu,'').replace(/\s*(?:[|\-–—]\s*)?(?:QG\s*)?BALTIGO\s*$/i,'').replace(/\s+/g,' ').trim() || String(name);
const initials = text => {const words=cleanName(text).replace(/[^\p{L}\p{N} ]/gu,' ').trim().split(/\s+/).filter(Boolean); return ((words[0]?.[0] || '?') + (words[1]?.[0] || '')).toUpperCase();};
